'use strict';

/** A Home grid card for an open project (renderer homeGridItems). */
interface HomeGridOpenItem {
  kind: 'open';
  /** The project's tab. */
  id: string;
  path: string;
  pinned: boolean;
  name: string;
  favicon: string | null;
  /** The preview's screenshot, once one was captured. */
  thumb?: string;
  state: 'sleeping' | 'running' | 'loading';
  meta: string;
  /** Infinity: open projects lead the recency sort. */
  when: number;
}
/** A Home grid card for a recent project that isn't open (renderer homeGridItems). */
interface HomeGridRecentItem {
  kind: 'recent';
  path: string;
  pinned: boolean;
  name: string;
  favicon: string | null | undefined;
  meta: string;
  whenLabel: string;
  /** When it was last opened; 0 when unknown. */
  when: number;
}
/** A Home grid card, read without narrowing (the other kind's fields are undefined). */
type HomeGridItem = LooseUnion<HomeGridOpenItem | HomeGridRecentItem>;
/**
 * project:open's answer as openProjectPath returns it: on a failure it puts the
 * folder on the answer (the node-missing retry reopens it).
 */
type OpenProjectResultWithDir = OpenProjectResult & { repoDir?: string };
/** An open's answer as handleOpenResult reads it: openProjectPath's or github:open's. */
type HandledOpenResult = LooseUnion<OpenGitHubResult | Extract<OpenProjectResultWithDir, { ok: false }>>;
/** The first-run panes of Home's create view (index.html's `.fr-tab[data-fr]`). */
type HomeFirstRunPane = 'template' | 'github' | 'folder' | 'migrate';
/** The rail's collapsible sections (renderer railSectionHeading). */
type RailSection = 'projects' | 'recents';
/**
 * Where a rail menu opens: a mouse event, or a stand-in point under the row's
 * "more" button. The menus read only the point; the optional methods let the
 * stand-in event (renderProjectsRail's "more" button) carry no-op ones.
 */
type RailMenuPoint = Pick<MouseEvent, 'clientX' | 'clientY'> & Partial<Pick<MouseEvent, 'preventDefault' | 'stopPropagation'>>;
/** The rail's project list (#railProjects), with what renderProjectsRail keeps on it. */
interface RailProjectsElement extends HTMLDivElement {
  /** The markup last rendered, to skip a redraw that changes nothing. */
  _html?: string;
  /** Removes the Recents hover card's listeners (wireRecentHoverCards). */
  _disposeRecentHover?: () => void;
  /** Remeasures the titles when the rail changes width (wireRailTitleScan). */
  _titleResizeObserver?: ResizeObserver;
}
/** A rail title's clip; one that scrolls on hover restarts its scan when remeasured (renderer wireRailTitleScan). */
interface RailTitleClip extends Element { _restartTitleScan?: () => void }

const $ = <K extends string>(id: K): ElementById<K> => document.getElementById(id) as ElementById<K>;
document.addEventListener('pointerdown', () => { document.documentElement.dataset.focusInput = 'pointer'; }, true);
document.addEventListener('keydown', event => {
  if (!['Shift', 'Control', 'Alt', 'Meta'].includes(event.key)) document.documentElement.dataset.focusInput = 'keyboard';
}, true);
// One live canvas per project; terminal threads only keep view state.
function persistThreadPreview(tab: Tab | null = activeTab()): void {
  tab?._threadPreview?.save();
}

// Field visibility: the window's uncaught errors and unhandled rejections become
// an anonymous app_error event. windowErrors.ts listens for them (index.html
// loads it before every other script) and main's errorReport.ts owns the
// privacy rules.

const routeNav = window.RadialNavigation;
const fuzzy = window.RadialFuzzy;
const viewportFit = window.RadialViewport;

// Inline a Central icon (from the generated, only-used set). Inherits currentColor.
function icon(name: string, size = 16): string {
  const svg = (window.RADIAL_ICONS && window.RADIAL_ICONS[name]) || '';
  return svg ? svg.replace('<svg ', `<svg class="ic" width="${size}" height="${size}" `) : '';
}
// First candidate name that actually resolved (icon set ships only used icons).
function iconAny(names: string[], size = 16): string {
  for (const n of names) { const s = icon(n, size); if (s) return s; }
  return '';
}
// Select carets come from the icon set too, so the stylesheet holds no icon
// drawings: builds from source swap the set, and CSS can't follow on its own.
(function setSelectCaret() {
  const svg = icon('IconChevronDownSmall', 12);
  if (!svg) return;
  const grey = svg.replace(/currentColor/g, '#969ba5');
  document.documentElement.style.setProperty('--select-caret', `url("data:image/svg+xml,${encodeURIComponent(grey)}")`);
})();

