function brandLogo(name: string, size = 14): string {
  const svg = BRAND_SVG[name];
  return svg ? svg.replace('<svg ', `<svg class="brand-ic" width="${size}" height="${size}" `) : '';
}
// A neutral rotating loader (the reload-arrow look) for async loads. We swap a
// button's icon to this while it spins, so a semantic icon — e.g. the cloud —
// never rotates (a spinning cloud reads as odd).
function loaderSvg(size = 14): string {
  return `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a9 9 0 1 1-2.64-6.36L21 8"/><path d="M21 3v5h-5"/></svg>`;
}
// Show the spinning loader on `spinEl` (replacing the icon in `iconEl`, or
// `spinEl` itself) for the duration of a load. Returns a restore fn.
function startSpinLoader(spinEl: Element | null | undefined, iconEl?: Element | null, size = 14): () => void {
  if (!spinEl) return () => {};
  const target = iconEl || spinEl;
  const prev = target.innerHTML;
  target.innerHTML = loaderSvg(size);
  spinEl.classList.add('spinning');
  return () => { spinEl.classList.remove('spinning'); target.innerHTML = prev; };
}

// --- theme (light / dark) --------------------------------------------------
const THEME_BG: { light: string; dark: string; [theme: string]: string | undefined } = { light: '#f2efed', dark: '#0b0a09' };
function currentTheme(): string { try { return localStorage.getItem('radial.theme') || 'dark'; } catch { return 'dark'; } }
function applyTheme(theme: string): void {
  const light = theme === 'light';
  document.documentElement.classList.toggle('light', light);
  try { localStorage.setItem('radial.theme', theme); } catch {}
  try { window.radial.setWindowBg(THEME_BG[theme] || THEME_BG.dark); } catch {}
}
applyTheme(currentTheme()); // apply the persisted theme as early as possible

function transparentSidebar(): boolean {
  try { return localStorage.getItem('radial.transparentSidebar') === '1'; } catch { return false; }
}
function applySidebarTransparency(on: boolean): void {
  document.documentElement.classList.toggle('sidebar-transparent', on);
  try { localStorage.setItem('radial.transparentSidebar', on ? '1' : '0'); } catch {}
}
applySidebarTransparency(transparentSidebar());

// When on, a build error that appears shortly after a sync/branch-switch is
// auto-handed to the agent (the "I pulled latest and it broke" case).
// Framework dev toolbars (Next.js indicator, Astro toolbar) in the preview:
// hidden by default; this setting turns them back on for people who want them.
function devToolbarsOn(): boolean { try { return localStorage.getItem('radial.devToolbars') === '1'; } catch { return false; } }
// Canvas drag-to-reorder switch (default OFF — Layers is the reliable reorder
// surface until the axis-aware, live-reflow canvas drag ships behind this flag).
// The ⌘E / A add palette is EXPERIMENTAL ("we may never ship
// that or the design panel"): its shortcuts are off by default so people don't
// run into it; the ⌘K entry stays, labeled, for anyone who wants it.
// ONE hidden experimental mode. Off: experimental panels are
// closed and absent from every picker, their shortcuts are inert, ⌘K shows none
// of their commands. On: they appear, tagged, with a note that they're rough,
// possibly broken, and may be removed. The only way in is typing "experimental"
// into ⌘K — deliberate, never accidental.
function expOn(): boolean { try { return localStorage.getItem('radial.experimental') === '1'; } catch { return false; } }
function expCloseAll(s: ToolPanelState): void {
  const g: Record<string, ToolPanelGroup> = s._groups || {};
  const exp = TOOL_PANELS.filter((d) => d.experimental).map((d) => d.id);
  Object.keys(g).forEach((k) => {
    const gr = g[k]; gr.panels = (gr.panels || []).filter((m) => !exp.includes(m));
    if (!gr.panels.includes(gr.active)) gr.active = gr.panels[0];
    if (gr.panels.length <= 1) { if (gr.panels[0] && s[gr.panels[0]]) s[gr.panels[0]].pos = Object.assign({}, s[gr.panels[0]].pos, gr.pos || {}); delete g[k]; }
  });
  exp.forEach((id) => { if (s[id]) { s[id].open = false; s[id].pinned = false; s[id].host = null; } });
}
function setExperimental(on: boolean): void {
  try { localStorage.setItem('radial.experimental', on ? '1' : '0'); } catch {}
  const s = tpState();
  if (!on) expCloseAll(s);
  tpSave(); renderPanelDock(); renderQuickAdjust();
  toast(on ? 'Experimental features on. They are tagged, rough, and may be removed.' : 'Experimental features off.', on ? '' : 'ok');
}
const TP_EXP_NOTE = '<div class="tp-exp-note">Experimental. Rough, possibly broken, and we may not keep it. For design changes, ask the agent.</div>';
function expAddOn(): boolean { try { return expOn() && localStorage.getItem('radial.experimental.add') === '1'; } catch { return false; } }
let _expAddHintAt = 0;
function expAddBlocked(): void {
  if (Date.now() - _expAddHintAt > 60000) { _expAddHintAt = Date.now(); if (expOn()) toast('Add element shortcuts are off. Turn them on from ⌘K.', ''); }
}
function canvasReorderOn(): boolean { try { return expOn() && localStorage.getItem('radial.canvasReorder') === '1'; } catch { return false; } }
function setCanvasReorder(on: boolean): void {
  try { localStorage.setItem('radial.canvasReorder', on ? '1' : '0'); } catch {}
  for (const t of tabs) { try { if (t.webview) t.webview.send('radial:set-canvas-reorder', !!on); } catch {} }
}
function setDevToolbars(on: boolean): void {
  try { localStorage.setItem('radial.devToolbars', on ? '1' : '0'); } catch {}
  tabs.forEach((t) => { try { if (t.webview) t.webview.send('radial:dev-toolbars', !!on); } catch {} });
}
// Empty containers outlined and given height while the select tool is on.
// OFF by default ("we don't need that on by default");
// a preference under Settings → Preview.
function revealEmptyOn(): boolean { try { return localStorage.getItem('radial.revealEmpty') === '1'; } catch { return false; } }
function setRevealEmpty(on: boolean): void {
  try { localStorage.setItem('radial.revealEmpty', on ? '1' : '0'); } catch {}
  tabs.forEach((t) => { try { if (t.webview) t.webview.send('radial:reveal-empty', !!on); } catch {} });
}

function autoFixAfterSync(): boolean { try { return localStorage.getItem('radial.autofixSync') === '1'; } catch { return false; } }
function setAutoFixAfterSync(on: boolean): void { try { localStorage.setItem('radial.autofixSync', on ? '1' : '0'); } catch {} }
// Dot-matrix "flicker" loader (keyframes live in styles.css). Each lit cell
// ripples on/off on its own staggered timing for an organic shimmer.
function flickerLoader(): string {
  const A = (cx: number, cy: number, anim: string) => `<circle class="on" cx="${cx}" cy="${cy}" r="2" opacity="0" style="animation:${anim} var(--flicker-dur) linear infinite"/>`;
  const off = (cx: number, cy: number) => `<circle cx="${cx}" cy="${cy}" r="2"/>`;
  // base grid (unlit) + lit overlays on the cells that animate
  let s = '';
  for (let y = 3; y <= 27; y += 6) for (let x = 3; x <= 27; x += 6) s += off(x, y);
  s += A(9, 3, 'fs00000111100') + A(15, 3, 'fs00001111111') + A(21, 3, 'fs00000111100');
  s += A(9, 9, 'fs00001111100') + A(15, 9, 'fs00011111000') + A(21, 9, 'fs00001111110');
  s += A(9, 15, 'fs00011110000') + A(15, 15, 'fs00111111000') + A(21, 15, 'fs00011110000');
  s += A(9, 21, 'fs00111111000') + A(15, 21, 'fs00111100100') + A(21, 21, 'fs00111110000');
  s += A(9, 27, 'fs00111000000') + A(15, 27, 'fs01110100000') + A(21, 27, 'fs00111001000');
  return `<svg class="flicker" viewBox="0 0 30 30" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Working"><title>Working</title>${s}</svg>`;
}

// One entry per open project (tab).
const tabs: Tab[] = [];
let activeId: string | null = null;
let tabSeq = 0;
let homeActive = false;

// ── The Home terminal (plans/radial-agent-native.md) ─────────────────────────
// A pseudo-tab that lives OUTSIDE tabs[] — session save, the free-plan cap, the
// rail's project rows and the home grid never see it — but is shaped like one,
// so every terminal path works unchanged. Its agent runs in the projects folder
// with the `radial` CLI on PATH: the one session a phone can drive across sites.
// Started on demand (the composer's first send), never at boot.
const homeTab: HomeTab = { id: 'home', home: true, name: 'Home', pageTitle: null, repoDir: null, terminals: [], activeTerminalId: null, term: null, composerImages: [], _sleptAgents: null };
function agentTab(): AnyTab | null { return (homeActive || !activeId) ? (homeTab.repoDir ? homeTab : null) : activeTab(); }
function tabById(id: string): AnyTab | null { return id === 'home' ? homeTab : (tabs.find((t) => t.id === id) || null); }
function agentTabs(): AnyTab[] { return homeTab.repoDir ? [homeTab, ...tabs] : tabs; }
let _homeTabInit: Promise<void> | null = null;
function initHomeTab(): Promise<void> {
  if (_homeTabInit) return _homeTabInit;
  _homeTabInit = (async () => {
    try {
      const info = await window.radial.homeInfo();
      if (!info || !info.cwd) return;
      homeTab.repoDir = info.cwd;
      homeTab._sleptAgents = (info.sleptAgents || []).length ? info.sleptAgents : null;
      await reattachProjectTerminals(homeTab);
    } catch {}
  })();
  return _homeTabInit;
}
function showHomeDock(): void { if (!homeActive || !homeTab.repoDir) return; setRightTab('terminal'); }
function termEmpty(show: boolean): void { const e = $('termEmpty'); if (e) e.hidden = !show; if (show) termOpening(null); }
// "Opening <project>…" holds the agent pane while a switched-to project's own
// session attaches, so the previous project's terminal never lingers there.
function termOpening(text: string | null): void {
  const e = $('termOpening'); if (!e) return;
  e.hidden = !text; e.firstElementChild!.textContent = text || '';
  clearTimeout(termOpening.timer);
  if (text) termOpening.timer = setTimeout(() => termOpening(null), 20000); // never a stale claim if no session attaches
}
declare namespace termOpening { let timer: TimerId | undefined; }
// Switch the agent pane the moment the project changes: the target's mounted
// terminal shows at once, otherwise the placeholder does until it attaches.
function showAgentPaneFor(tab: AnyTab): void {
  const term = tab.term && tab.term.el && tab.term.xterm && !tab.term.detached && (tab.terminals || []).includes(tab.term) ? tab.term : null;
  [...document.querySelectorAll('.term-instance.active')].forEach((e) => { if (!term || e !== term.el) e.classList.remove('active'); });
  if (term) { term.el!.classList.add('active'); termOpening(null); setTimeout(() => fitActiveTerm(), 0); }
  else termOpening(`Opening ${tab.name || 'project'}…`);
}
