function providerLogo(provider: string | null | undefined, size = 14): string { return provider === 'codex' ? brandLogo('openai', size) : provider === 'cursor' ? brandLogo('cursor', size) : brandLogo('claude', size); }
// <option> list for a model-ref picker, grouped by provider (native <select>
