// Persist which projects are open + which is active, so we can reopen them next
// launch (Figma-style). Skipped during restore to avoid clobbering the saved set.
let restoringSession = false;
function saveSession(): void {
  if (restoringSession) return;
  const open = tabs.map((t) => t.repoDir).filter(Boolean);
  const active = activeTab() ? activeTab()!.repoDir : (open[0] || null);
  window.radial.sessionSave(open, active);
}

