  justifyContent: 'flex-start', alignItems: 'flex-start', lineHeight: 1.5, letterSpacing: 0,
  textTransform: 'none', color: '', bgColor: '', opacity: 100, borderWidth: 0, shadow: 'none', maxWidth: 0,
  position: 'static', insetTop: null, insetRight: null, insetBottom: null, insetLeft: null,
