  const deltas = dsMode === 'hover' ? (adj.hdeltas || {}) : adj.deltas;
  const grid2 = (a: string, b: string) => `<div style="display: flex; flex-direction: column; gap: 4px">`
    + `<div style="display: flex; gap: 6px">${a}</div><div style="display: flex; gap: 6px">${b}</div></div>`;
  const bpNow = sel && tpBp(sel);
