    + `<button data-ds-state="base" class="${dsMode === 'base' ? 'on' : ''}" aria-pressed="${dsMode === 'base'}">Default</button>`
    + `<button data-ds-state="hover" class="${dsMode === 'hover' ? 'on' : ''}" aria-pressed="${dsMode === 'hover'}" title="Edits apply on :hover">Hover</button>`
    + `<span class="ds-bp-chip${bpNow ? ' scoped' : ''}" title="${bpNow ? `Changes here apply at ${bpNow.bp}px and below. Desktop keeps its styles.` : 'Changes here apply at every width.'}">${bpNow ? `\u2264${bpNow.bp}px` : 'Desktop'}</span>`
    + `</div>`;

