    const modeBtn = (dim: TpSizeDim, mode: TpDsSizeMode) => `<button type="button" class="ds-x ds-szmode" data-ds-sizemode="${dim}" title="Fixed / Hug contents / Fill container" aria-haspopup="menu">${mode === 'fixed' ? '' : TP_SIZE_LABEL[mode]}${szCaret}</button>`;
    let b = tpRow([tpCol(`Width ${modeBtn('width', wMode)}`, tpWell('w', 'width', wMode === 'fixed' ? cur.width : TP_SIZE_LABEL[wMode], 'width' in deltas)),
      tpCol(`Height ${modeBtn('height', hMode)}`, tpWell('h', 'height', hMode === 'fixed' ? cur.height : TP_SIZE_LABEL[hMode], 'height' in deltas))])
      + tpRow([tpCol('Min width', tpWell('minw', 'min-width', cur.minWidth || null, 'min-width' in deltas)),
        tpCol('Min height', tpWell('minh', 'min-height', cur.minHeight || null, 'min-height' in deltas))])
      + tpRow([tpCol('Max width', tpWell('maxw', 'max-width (Tailwind ladder)', cur.maxWidthName || QA_MAXW_NAME(cur.maxWidth), 'max-width' in deltas)),
        tpCol('Max height', tpWell('maxh', 'max-height', cur.maxHeight || null, 'max-height' in deltas))])
      + tpRow([tpCol('Aspect', tpWell('aspect', 'aspect-ratio (e.g. 16/9)', cur.aspectRatio || null, 'aspect-ratio' in deltas)), TP_HOLE]);
