  const nodes = t.nodes || [];
  for (let i = 0; i < nodes.length; i++) {
    if (!collapsed.has(nodes[i].selector)) continue;
    for (let j = i + 1; j < nodes.length && nodes[j].depth > nodes[i].depth; j++) hidden.add(j);
  }
