  slashEl.style.display = 'block';
  slashEl.innerHTML =
    `<div class="slash-foot slash-foot-top"><button type="button" class="slash-add" id="slashAddSkill">${icon('IconFolderAddLeft', 13)}<span>Add a skill…</span></button></div>`
    + items.map((it, i) =>
      `<div class="slash-item${i === slashMenu.sel ? ' sel' : ''}" data-i="${i}">`
      + `<span class="slash-name">/${escapeHtml(it.name)}</span>`
      + `<span class="slash-desc">${escapeHtml(it.description || '')}</span>`
      + `<span class="slash-kind">${it.kind === 'skill' ? 'skill' : 'cmd'}</span></div>`).join('');
