  mentionEl.style.display = 'block';
  mentionEl.innerHTML = items.map((it, i) =>
    `<div class="slash-item${i === mentionMenu.sel ? ' sel' : ''}" data-i="${i}">`
    + `<span class="slash-name">@${escapeHtml(it.label)}</span>`
    + `<span class="slash-desc">${escapeHtml(it.desc || '')}</span>`
    + `<span class="slash-kind">${it.kind}</span></div>`).join('');
