    row.onmousedown = (e) => { e.preventDefault(); mentionMenu.sel = +row.dataset.i!; acceptMention(mentionMenu.items[mentionMenu.sel]); };
    row.onmouseenter = () => { mentionMenu.sel = +row.dataset.i!; paintMentionSel(); };
