$('agentInput').addEventListener('input', onAgentInputChanged);
// Clicking a menu row keeps focus (mousedown preventDefault); any other blur closes it.
$('agentInput').addEventListener('blur', () => { if (slashMenu.open) setTimeout(hideSlashMenu, 100); if (mentionMenu.open) setTimeout(hideMentionMenu, 100); });
$('cancelLink').onclick = closeLinkModal;
