  const tab = activeTab(); if (!tab || (tab.vz || 1) <= 1.001) return;
  const shield = document.createElement('div');
  shield.id = 'spacePanShield';
  document.body.appendChild(shield);
  spacePan = { shield, drag: null };
  shield.addEventListener('pointerdown', (ev) => { spacePan!.drag = { x: ev.clientX, y: ev.clientY }; shield.classList.add('dragging'); shield.setPointerCapture(ev.pointerId); });
