window.addEventListener('blur', endSpacePan); // a lost keyup must not strand the shield

window.radial.onFullscreen((on) => { document.body.classList.toggle('is-fullscreen', on); });

// Keep the fitted artboard in sync with any geometry change. A ResizeObserver
// catches dock/sidebar drags as well as ordinary window resize.
// Both observers feed the shared coalescer — dock drags, sidebar drags, and
// window resizes all collapse into one refit per frame.
if (window.ResizeObserver) {
  const ro = new ResizeObserver(() => scheduleRefit());
  ro.observe($('previews'));
  ro.observe($('preview'));
}

// --- clamped centering for the two top bars ---------------------------------
// The lock/breakpoint switch and the arrows+url group sit on their bar's TRUE
// 50% while there's room; as the side clusters close in they slide off-center
// just enough to never overlap, and only when nothing fits does the bar get
// .center-flow (the cluster rejoins the flex flow).
function layoutCenterCluster(bar: HTMLElement | null, center: HTMLElement | null, leftEdgeEl: Element | null, rightEdgeEl: Element | null, extraLeft: number, vTransform: string) {
  if (!bar || !center) return;
  const barR = bar.getBoundingClientRect();
  if (!barR.width) return;
  const w = center.offsetWidth;
  const minL = (leftEdgeEl ? Math.max(0, leftEdgeEl.getBoundingClientRect().right - barR.left) : 0) + (extraLeft || 0) + 8;
  const maxL = (rightEdgeEl ? rightEdgeEl.getBoundingClientRect().left - barR.left : barR.width) - w - 8;
  const cramped = minL > maxL;
  const wasFlow = bar.classList.contains('center-flow');
  bar.classList.toggle('center-flow', cramped);
  if (cramped) { center.style.left = ''; center.style.transform = ''; return; }
  if (wasFlow) { center.style.left = ''; center.style.transform = ''; scheduleBarLayout(); return; } // re-measure after leaving flow
  const ideal = (barR.width - w) / 2;
  center.style.left = Math.round(Math.max(minL, Math.min(ideal, maxL))) + 'px';
  // Horizontal position is exact px now — keep only each bar's own vertical anchoring.
  center.style.transform = vTransform || 'none';
}
function layoutCenteredBars() {
  const tc = document.querySelector<HTMLElement>('.topbar-center');
  layoutCenterCluster($('topbar'), tc, $('contextToggle'), document.querySelector('.topbar-actions'), 0, 'none');
  // vNext: the browser-nav row is plain flex (the url bar fills it) — only the topbar centers.
}
let _barLayoutRaf = 0;
function scheduleBarLayout() {
  if (_barLayoutRaf) return;
  _barLayoutRaf = requestAnimationFrame(() => { _barLayoutRaf = 0; layoutCenteredBars(); });
}
if (window.ResizeObserver) {
  const bro = new ResizeObserver(scheduleBarLayout);
  bro.observe($('topbar'));
  bro.observe($('browserNav'));
  bro.observe(document.querySelector('.topbar-actions')!);
}
scheduleBarLayout();
scheduleRefit();

// --- sidebar tabs + search ------------------------------------------------
// Scope to the left sidebar — the right dock reuses .side-tab styling but is
// wired separately (data-rt), so an unscoped selector would clobber it.
[...document.querySelectorAll<HTMLElement>('#sidebar .side-tab')].forEach((b) => { b.onclick = () => switchSidePane(b.dataset.pane as 'pages' | 'launch'); });
function switchSidePane(pane: 'pages' | 'context' | 'launch') {
  ['pages', 'context', 'launch'].forEach((p) => { const el = $('pane-' + p); if (el) el.hidden = p !== pane; });
  [...document.querySelectorAll<HTMLElement>('#sidebar .side-tab')].forEach((b) => b.classList.toggle('active', b.dataset.pane === pane));
  $('sideSearch').style.display = pane === 'pages' ? '' : 'none';
  if (pane === 'context') { const t = activeTab(); if (t) renderContext(t); }
  if (pane === 'launch') { const t = activeTab(); if (t) loadLaunch(t.repoDir); }
}

// ── Pre-launch check ──────────────────────────────────────────────────────
// A per-project readiness checklist. Increment 1 is deterministic only: the
// main process fetches each page from the running preview and reports a hard
// pass / review / fix per check. Agent-judged dimensions (visual consistency,
// copy, responsive polish) come later and will read as a distinct state, never
// a plain green check, so a verified green always means measured-and-true.

const LAUNCH_DOT = { pass: 'ok', warn: 'warn', fail: 'bad', na: 'na' };
let launchBusy = false;
let launchLast: LaunchCheckScan | null = null;

async function loadLaunch(repoDir: string) {
  if (!repoDir) return;
  let cached = null;
  try { cached = await window.radial.launchCheckGet(repoDir); } catch {}
  renderLaunch(cached);
}

async function runLaunch(repoDir: string | null) {
  if (!repoDir || launchBusy) return;
  launchBusy = true;
  const body = $('launchBody');
  if (body) body.innerHTML = '<div class="launch-empty"><div class="muted">Scanning pages…</div></div>';
  let report: LaunchPaneReport = null;
  try { report = await window.radial.launchCheckRun(repoDir); }
  catch (e) { report = { ok: false, error: String((e && (e as Error).message) || e) }; }
  launchBusy = false;
  renderLaunch(report);
}

function renderLaunch(report: LaunchPaneReport) {
  const body = $('launchBody');
  if (!body) return;
  const t = activeTab();
  const repoDir = t && t.repoDir;

  if (!report || report.ok === false) {
    const msg = report && report.error
      ? report.error
      : 'Check the site is ready to publish: titles, meta descriptions, alt text, headings, social tags, and internal links across every page.';
    body.innerHTML =
      '<div class="launch-empty"><p class="muted">' + escapeHtml(msg) + '</p>' +
      '<button class="btn btn-primary" id="launchRunBtn">Run check</button></div>';
    wireLaunchRun(repoDir);
    return;
  }

  launchLast = report;
  const c = report.counts || {};
  const summary =
    '<div class="launch-summary"><div class="launch-tallies">' +
    launchTally('ok', c.pass || 0, 'verified') +
    launchTally('warn', c.warn || 0, 'to review') +
    launchTally('bad', c.fail || 0, 'to fix') +
    '</div><div class="launch-meta"><span class="muted">' +
    escapeHtml(String(report.pageCount || 0)) + ' pages, scanned ' + escapeHtml(timeAgo(report.scannedAt)) +
    '</span><button class="btn" id="launchRunBtn">Re-run</button></div></div>';

  const unreachable = (report.unreachable && report.unreachable.length)
    ? '<div class="launch-warnrow">' + escapeHtml(report.unreachable.length + ' page(s) did not load and were skipped.') + '</div>'
    : '';

  const order: string[] = [];
  const byCat = new Map<string, LaunchCheckItem[]>();
  for (const r of (report.results || [])) {
    if (!byCat.has(r.category)) { byCat.set(r.category, []); order.push(r.category); }
    byCat.get(r.category)!.push(r);
  }
  let items = '';
  for (const cat of order) {
    items += '<div class="launch-group">' + escapeHtml(cat) + '</div>';
    for (const r of byCat.get(cat)!) items += launchItem(r);
  }

  body.innerHTML = summary + unreachable + '<div class="launch-list">' + items + '</div>';
  wireLaunchRun(repoDir);
  [...body.querySelectorAll<HTMLElement>('.launch-item.has-issues .launch-item-head')].forEach((h) => {
    h.onclick = () => h.parentElement!.classList.toggle('open');
  });
  [...body.querySelectorAll<HTMLElement>('.launch-fix')].forEach((b) => {
    b.onclick = (e) => { e.stopPropagation(); fixLaunchIssue(b.dataset.check!); };
  });
}

// Hand a failing check to the agent: build a targeted prompt from its issues and
// route it to whichever agent surface is open (live CLI up front, else the chat),
// mirroring how pulled comments are dispatched. The user reviews and sends.
function fixLaunchIssue(id: string) {
  const tab = activeTab();
  if (!tab || !launchLast) return;
  const check = (launchLast.results || []).find((r) => r.id === id);
  if (!check) return;
  const lines = (check.issues || []).map((i) => '- ' + (i.route ? i.route + ': ' : '') + i.msg).join('\n');
  const prompt = 'Fix the "' + check.label + '" pre-launch check. ' + (check.hint || '') +
    '\n\nIssues found:\n' + lines +
    '\n\nMake the minimal edits to resolve these. Do not change unrelated content.' +
    '\nWhen you are done, create an empty file at .radial/run-launch-check. Radial re-scans and updates the checklist from it.';
  const display = 'Fix: ' + check.label;
  // Arm the deterministic follow-up: re-scan whenever the agent goes quiet until
  // this check passes (or 10 min). The prompt's run-launch-check contract still
  // works when the agent obliges; this closes the loop when it doesn't.
  tab._launchRescan = { id: check.id, at: Date.now(), lastScan: 0 };
  engineSend(tab, { text: prompt, label: display, submit: true });
}

function launchTally(dot: string, n: number, label: string) {
  return '<span class="launch-tally"><span class="ldot ' + dot + '"></span>' + n + ' <span class="muted">' + escapeHtml(label) + '</span></span>';
}

function launchItem(r: LaunchCheckItem) {
  const dot = LAUNCH_DOT[r.status] || 'na';
  const hasIssues = !!(r.issues && r.issues.length);
  const issues = hasIssues
    ? '<div class="launch-issues">' + r.issues.map((i) => {
        const where = i.route ? '<span class="launch-where">' + escapeHtml(i.route) + '</span> ' : '';
        return '<div class="launch-issue">' + where + escapeHtml(i.msg) + '</div>';
      }).join('') +
      '<button class="btn-mini launch-fix" data-check="' + escapeHtml(r.id) + '">Fix with agent</button>' +
      '</div>'
    : '';
  return (
    '<div class="launch-item ' + dot + (hasIssues ? ' has-issues' : '') + '" data-check="' + escapeHtml(r.id) + '">' +
    '<div class="launch-item-head" title="' + escapeHtml(r.hint || '') + '">' +
    '<span class="ldot ' + dot + '"></span>' +
    '<span class="launch-item-main"><span class="launch-item-label">' + escapeHtml(r.label) + '</span>' +
    '<span class="launch-item-sum muted">' + escapeHtml(r.summary || '') + '</span></span>' +
    (hasIssues ? '<span class="launch-caret"></span>' : '') +
    '</div>' + issues + '</div>'
  );
}

function wireLaunchRun(repoDir: string | null) {
  const btn = $('launchRunBtn');
  if (btn) btn.onclick = () => runLaunch(repoDir);
}

// ── Canonical layout ──────────────────────────────────────────────────────
// The work dock is always the left-hand column. Pages, Context, and History
// open from the browser-nav panel; there is no alternate right-dock layout.
function initializeCanonicalLayout() {
  try { localStorage.removeItem('radial.layout'); } catch {}
  const tab = activeTab();
  if (tab) {
    ensureRightDock();
    // Measure AFTER the new layout reflows — a synchronous applyWidth here reads
    // the old stage size and bakes in a stale canvas scale (the dark-band bug).
    applyWidth(tab);
    requestAnimationFrame(() => { const t = activeTab(); if (t) applyWidth(t); });
  }
  renderPagesButton(tab);
  renderProjectsRail();
}
$('pagesBtn').onclick = (e) => { e.stopPropagation(); togglePagesPanel(); };
