// Full-page 2× screenshot → Downloads (CDP captureBeyondViewport in main —
// one shot, no stitching; ported behavior from Radial Viewport). View menu only.
async function saveFullPageShot(tab?: Tab | null) {
  tab = tab || activeTab();
  if (!tab || !tab.webview) return;
  toast('Capturing full page…', '');
  let wcId = null;
  try { wcId = tab.webview.getWebContentsId(); } catch {}
  if (wcId == null) { toast('Couldn’t reach the preview', 'err'); return; }
  const route = normRoute(tab.currentRoute || '/');
  const slug = route === '/' ? 'home' : route.replace(/^\//, '').replace(/\//g, '-');
  const name = `${tab.name || 'site'}-${slug}-full@2x-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '')}`;
  const res = await window.radial.fullPageShot(wcId, name);
  if (res && res.ok) toast(`Saved to Downloads: ${res.path.split('/').pop()}${res.scale === 1 ? ' (1×: page too tall for 2×)' : ''}`, 'ok');
  else toast(`Full-page capture failed${res && res.error ? `: ${res.error}` : ''}`, 'err');
}
