// Clicking anywhere that isn't a typing surface drops focus out of the
// composer/terminal, so the single-key hotkeys (1/2/3, V/S/C/I, ⇧R) work right
// away — sidebar rows, dock tabs, and empty chrome all release focus, not just
// bare gutters. Focus is kept only when the click goes INTO another field, an
// open menu, a terminal, or a control belonging to the focused field's own
// surface (the composer's toolbar, the quick-edit pill, a comment card) — a
// blanket button/link exclusion here used to keep the keystream captive after
// clicking any sidebar row, since nearly all chrome is buttons.
// .term-instance matters: a click into a terminal focuses xterm's hidden
// textarea, and blurring it here made terminals impossible to type into.
document.addEventListener('mousedown', (e) => {
  const ae = document.activeElement as HTMLElement | null;
  if (!isTypingTarget(ae)) return;
  const t = e.target;
  if (!(t instanceof Element)) return;
  if (t.closest('input, textarea, select, [contenteditable], .menu, .branch-menu, .cstat-menu, .slash-menu, .mention-menu, .nav-url-menu, .cm-card, .modal-card, .term-instance')) return;
  const owner = ae!.closest && ae!.closest('#agentInputBar, .quick-edit, .comment-composer, .cm-card, .modal-card');
  if (owner && owner.contains(t)) return; // the field's own buttons keep its focus
  ae!.blur();
});
// Editable route bar: type a path, Enter to navigate — plus a page-search
// dropdown (ported from Radial Viewport): focus lists the site's pages,
// typing filters, arrows + Enter open a match; plain Enter keeps working as
// a raw route.
const navUrlMenu = document.createElement('div');
navUrlMenu.id = 'navUrlMenu';
navUrlMenu.className = 'nav-url-menu';
navUrlMenu.hidden = true;
document.body.appendChild(navUrlMenu);
let nmIndex = -1;

function nmLabel(p: ProjectPage) {
  const r = normRoute(p.route);
  if (r === '/') return 'Home';
  return routeDepth(r) >= 2 ? r.slice(r.indexOf('/', 1)) : r;
}
function nmSearch(q: string): ProjectPage[] {
  const t = activeTab();
  const pages = (t && t.pages) || [];
  if (!q) return pages;
  q = q.toLowerCase();
  const scored: [number, ProjectPage][] = [];
  for (const p of pages) {
    const route = normRoute(p.route).toLowerCase();
    const label = ((p.label || '') + ' ' + nmLabel(p)).toLowerCase();
    let s = -1;
    if (route.slice(1).startsWith(q) || route.startsWith(q)) s = 0;
    else if (label.startsWith(q)) s = 1;
    else if (route.includes(q)) s = 2;
    else if (label.includes(q)) s = 3;
    if (s >= 0) scored.push([s, p]);
  }
  return scored.sort((a, b) => a[0] - b[0] || a[1].route.localeCompare(b[1].route)).map((x) => x[1]);
}
function openNavUrlMenu() {
  const input = $('navUrl');
  const t = activeTab();
  if (!t) return;
  const raw = input.value.trim();
  const cur = normRoute(t.currentRoute || '/');
  // The current route sitting untouched in the field means "browse", not "filter".
  const q = (raw === cur || raw === '' || raw === '/') ? '' : raw.replace(/^\//, '');
  const items = nmSearch(q);
  nmIndex = -1;
  if (!items.length) { closeNavUrlMenu(); return; }
  navUrlMenu.innerHTML = '';
  items.forEach((p) => {
    const b = document.createElement('button');
    const r = normRoute(p.route);
    b.className = 'num-item' + (r === cur ? ' num-current' : '');
    b.innerHTML = `<span class="num-ic">${icon('IconPageText', 13) || ''}</span>`
      + `<span class="num-label">${escapeHtml(p.label || nmLabel(p))}</span>`
      + `<span class="num-route">${escapeHtml(r)}</span>`
      + `<span class="num-gear" title="Page settings">${icon('IconSettingsGear1', 13) || ''}</span>`;
    // mousedown (not click): preventDefault keeps the input focused → no blur race.
    b.addEventListener('mousedown', (ev) => {
      ev.preventDefault(); closeNavUrlMenu(); input.blur();
      const wantSettings = !!(ev.target as Element).closest('.num-gear');
      loadRoute(p.route, null, activeTab());
      // The drawer reads the current page — let the route land first.
      if (wantSettings) setTimeout(() => { try { openPageSettings(); } catch {} }, 120);
    });
    navUrlMenu.appendChild(b);
  });
  // Footer: create a page without leaving the bar (hands off to the agent).
  {
    const nb = document.createElement('button');
    nb.className = 'num-item num-new';
    nb.innerHTML = `<span class="num-ic">${icon('IconPlusMedium', 13) || '+'}</span><span class="num-label">New page</span>`;
    nb.addEventListener('mousedown', (ev) => { ev.preventDefault(); closeNavUrlMenu(); input.blur(); const a = $('pageAdd'); if (a && a.onclick) (a.onclick as () => void)(); });
    navUrlMenu.appendChild(nb);
  }
  const r = input.closest('.bn-url')!.getBoundingClientRect();
  navUrlMenu.style.left = Math.round(r.left) + 'px';
  navUrlMenu.style.top = Math.round(r.bottom + 6) + 'px';
  navUrlMenu.style.width = Math.round(r.width) + 'px';
  navUrlMenu.hidden = false;
}
function closeNavUrlMenu() {
  nmIndex = -1;
  if (navUrlMenu.hidden) return;
  animateOut(navUrlMenu, () => { if (nmIndex === -1) { navUrlMenu.hidden = true; navUrlMenu.innerHTML = ''; } });
}
function nmMove(delta: number) {
  const items = navUrlMenu.querySelectorAll('.num-item');
  if (!items.length) return;
  nmIndex = (nmIndex + delta + items.length) % items.length;
  items.forEach((el, i) => el.classList.toggle('active', i === nmIndex));
  items[nmIndex].scrollIntoView({ block: 'nearest' });
}
$('navUrl').addEventListener('keydown', (e) => {
  if (e.key === 'ArrowDown' && !navUrlMenu.hidden) { e.preventDefault(); nmMove(1); return; }
  if (e.key === 'ArrowUp' && !navUrlMenu.hidden) { e.preventDefault(); nmMove(-1); return; }
  if (e.key === 'Escape' && !navUrlMenu.hidden) { e.preventDefault(); e.stopPropagation(); closeNavUrlMenu(); return; }
  if (e.key !== 'Enter') return;
  e.preventDefault();
  const t = activeTab(); if (!t) return;
  const items = navUrlMenu.querySelectorAll('.num-item');
  if (nmIndex >= 0 && items[nmIndex]) { items[nmIndex].dispatchEvent(new MouseEvent('mousedown')); return; }
  closeNavUrlMenu();
  let r = $('navUrl').value.trim(); if (!r.startsWith('/')) r = '/' + r;
  loadRoute(r, null, t);
  $('navUrl').blur();
});
$('navUrl').addEventListener('focus', () => { $('navUrl').select(); openNavUrlMenu(); });
$('navUrl').addEventListener('input', openNavUrlMenu);
