// Keep the route bar + back/forward enablement in sync with the active page.
function renderBrowserNav(tab = activeTab()) {
  const url = $('navUrl'); if (!url) return;
  if (document.activeElement !== url) url.value = (tab && tab.currentRoute) || '/';
  const wv = tab && tab.webview;
  try { $('navBack').disabled = !(wv && wv.canGoBack && wv.canGoBack()); } catch { $('navBack').disabled = true; }
  try { $('navFwd').disabled = !(wv && wv.canGoForward && wv.canGoForward()); } catch { $('navFwd').disabled = true; }
}

