// Shown when an open hits NODE_NOT_FOUND. `onReady` retries the open that
// was interrupted.
let nodeModalRetry: (() => void) | null = null;
function openNodeModal(onReady: () => void) {
  nodeModalRetry = onReady;
  const st = $('nodeStatus'); st.style.display = 'none'; st.textContent = ''; st.classList.remove('np-err');
  $('nodeGo').disabled = false; $('nodeGo').textContent = 'Install & continue';
  $('nodeModal').style.display = 'flex';
}
function closeNodeModal() { $('nodeModal').style.display = 'none'; nodeModalRetry = null; }
