// Publish-with-deploy progress: the build gate streams here while a publish runs,
// so the user sees it verifying the build (and, if it has to fix it, the agent's
// work shows up live in the chat via the normal agent:event stream).
window.radial.onPublishEvent((p) => {
  if (!p) return;
  // Mirror the current step into the publish popover's live line, so the steps
  // stream where the user is looking (not just the log panel).
  const step = (t: string) => { const el = $('pmStatusStep'); if (el && t) el.textContent = t; };
  if (p.kind === 'status' && p.text) { log('[deploy] ' + p.text); step(p.text); }
  else if (p.kind === 'build_log' && p.text) p.text.split('\n').forEach((l) => { if (l.trim()) log('[build] ' + l.trim()); });
  else if (p.kind === 'gate') {
    if (p.status === 'ok') { log('[deploy] build passed, publishing'); step('Build passed, pushing…'); }
    else if (p.status === 'failed') { log('[deploy] build failed'); step('Build failed.'); }
    else if (p.status === 'skipped') { log('[deploy] no build step, publishing'); step('Pushing…'); }
  }
  // ('fixing' events died with the headless fix loop — a failed gate now comes
  // back as a result carrying fixPrompt, and the renderer offers Publish anyway
  // / Fix with agent; the handoff only happens on an explicit click.)
});

// Reopen last session's projects on launch (Figma-style) — the active project
// starts for real (it shows fast), everything else restores ASLEEP: no dev
// server, no agent processes, just its tab and rail entry. Clicking a sleeping
// project wakes it (session:setActive resumes, then its slept agents relaunch).
window.radial.onRestoreSession(async ({ open, active, crashed }) => {
  // Saved order IS the rail order (drag-to-reorder persists through it), so
  // open in exactly that order — bubbling the active project to the front
  // would scramble the arrangement on every restart. It still boots hot
  // (cold: false) and gets focused once, at the end.
  restoringSession = true;
  try {
    for (const dir of open || []) { if (!tabByRepo(dir)) await openProjectPath(dir, { cold: dir !== active }); }
  } finally {
    restoringSession = false;
  }
  const a = active && tabByRepo(active);
  if (a) switchTab(a.id); else saveSession();
  if (crashed) toast('Reopened your projects after an unexpected close.', 'ok');
});

