// One shared, body-level tooltip for every [data-tip] element. Positioned by JS
// so it escapes overflow-clipping ancestors and local stacking contexts, and
// flips/clamps to stay inside the viewport (the old CSS ::after could do neither).
(function initTooltips() {
  const tip = document.createElement('div');
  tip.id = 'tooltip';
  document.body.appendChild(tip);
  let anchor: Element | null = null, timer: TimerId | null = null;
  const MARGIN = 8, GAP = 8, DELAY = 350;

  function place() {
    if (!anchor || !document.body.contains(anchor)) return hide();
    const text = anchor.getAttribute('data-tip');
    if (!text) return hide();
    tip.textContent = text;
    tip.classList.remove('wrap');
    const r = anchor.getBoundingClientRect();
    let tw = tip.offsetWidth, th = tip.offsetHeight;
    // Wrap only if the label can't fit the viewport width on one line.
    if (tw > window.innerWidth - MARGIN * 2) { tip.classList.add('wrap'); tw = tip.offsetWidth; th = tip.offsetHeight; }
    const below = anchor.hasAttribute('data-tip-below');
    // Preferred side, then flip if it would clip off the top/bottom edge.
    let top = below ? r.bottom + GAP : r.top - th - GAP;
    if (!below && top < MARGIN) top = r.bottom + GAP;
    else if (below && top + th > window.innerHeight - MARGIN) top = r.top - th - GAP;
    top = Math.max(MARGIN, Math.min(top, window.innerHeight - th - MARGIN));
    // Center over the anchor, then clamp within the viewport.
    let left = r.left + r.width / 2 - tw / 2;
    left = Math.max(MARGIN, Math.min(left, window.innerWidth - tw - MARGIN));
    if (anchor.hasAttribute('data-tip-right')) {
      left = Math.max(MARGIN, Math.min(r.right + GAP, innerWidth - tw - MARGIN));
      top = Math.max(MARGIN, Math.min(r.top + (r.height - th) / 2, innerHeight - th - MARGIN));
    }
    tip.style.left = Math.round(left) + 'px';
    tip.style.top = Math.round(top) + 'px';
    tip.classList.add('show');
  }
  function show(el: Element) { anchor = el; clearTimeout(timer); timer = setTimeout(place, DELAY); }
  function hide() { anchor = null; clearTimeout(timer); tip.classList.remove('show'); }

  document.addEventListener('mouseover', (e) => {
    const el = e.target instanceof Element ? e.target.closest('[data-tip]') : null;
    if (el && el !== anchor) show(el);
  });
  document.addEventListener('mouseout', (e) => {
    if (anchor && !(e.relatedTarget && anchor.contains(e.relatedTarget as Node))) hide();
  });
  // Anything that can move or cover the anchor dismisses the tip immediately.
  document.addEventListener('mousedown', hide, true);
  window.addEventListener('scroll', hide, true);
  window.addEventListener('blur', hide);
})();

