// Scrub the width by dragging horizontally on the field (1px = 1px of logical
// width, live); a plain click without dragging focuses it so you can type.
(() => {
  const input = $('widthInput');
  let scrub: { startX: number; startW: number; moved: boolean } | null = null; // { startX, startW, moved }
  input.addEventListener('mousedown', (e) => {
    if (document.activeElement === input || !activeTab()) return; // editing → normal caret
    e.preventDefault(); // hold off focus until we know it's a click, not a drag
    scrub = { startX: e.clientX, startW: parseInt(input.value, 10) || DEFAULT_LOCK_WIDTH, moved: false };
    $('dragMask').style.display = 'block'; // keep the webview from swallowing the drag
  });
  window.addEventListener('mousemove', (e) => {
    if (!scrub) return;
    if (Math.abs(e.clientX - scrub.startX) > 2) scrub.moved = true;
    if (scrub.moved) setWidth(Math.max(280, Math.min(5000, scrub.startW + (e.clientX - scrub.startX))));
  });
  window.addEventListener('mouseup', () => {
    if (!scrub) return;
    const wasClick = !scrub.moved;
    scrub = null;
    $('dragMask').style.display = 'none';
    if (wasClick) input.focus(); // the focus listener selects-all → type to replace
  });
})();

