// The first time a server goes over the memory limit Radial restarts it: say so
// quietly, so a preview that blinks has a reason.
window.radial.onDevMemoryRestarted?.(({ repoDir, gb }) => {
  const tab = tabByRepo(repoDir);
  let pill = $('devMemPill');
  if (!pill) { pill = document.createElement('div'); pill.id = 'devMemPill'; pill.className = 'bottom-pill'; document.body.appendChild(pill); }
  pill.innerHTML = `<span class="bb-dot" style="background: #e0a93a"></span>`
    + `<span class="bb-title">Dev server used ${escapeHtml(String(gb))} GB</span>`
    + `<span class="bb-ctx">restarted${tab ? ` ${escapeHtml(tab.pageTitle || tab.name)}` : ''} to free memory</span>`
    + `<span class="bb-sep"></span>`
    + `<button class="bb-dismiss">Dismiss</button>`;
  pill.querySelector<HTMLButtonElement>('.bb-dismiss')!.onclick = () => pill.remove();
  setTimeout(() => { if (pill.isConnected && pill.textContent.includes('restarted')) pill.remove(); }, 15000);
});
// The memory ceiling tripped: the server was stopped deliberately, with a
// reason — surface it as an inline explanation, not a mystery sleep.
window.radial.onDevMemoryStopped(({ repoDir, gb }) => {
  const tab = tabByRepo(repoDir);
  let pill = $('devMemPill');
  if (!pill) { pill = document.createElement('div'); pill.id = 'devMemPill'; pill.className = 'bottom-pill'; document.body.appendChild(pill); }
  pill.innerHTML = `<span class="bb-dot" style="background: #e0a93a"></span>`
    + `<span class="bb-title">Dev server used ${escapeHtml(String(gb))} GB</span>`
    + `<span class="bb-ctx">stopped to protect your Mac</span>`
    + `<span class="bb-sep"></span>`
    + `<button class="bb-dismiss">Dismiss</button>`
    + `<button class="bb-act">Start again</button>`;
  pill.querySelector<HTMLButtonElement>('.bb-dismiss')!.onclick = () => pill.remove();
  pill.querySelector<HTMLButtonElement>('.bb-act')!.onclick = async () => {
    pill.remove();
    const t = tabByRepo(repoDir);
    if (t) { setLoading(true, 'Starting the dev server…'); await applyProjectRefresh(t, { forceRestart: true }); setLoading(false); }
  };
});

window.radial.onSessionResumed(({ repoDir, url }) => {
  const tab = tabByRepo(repoDir);
  if (!tab) return;
  const moved = tab.baseUrl !== url;
  tab.suspended = false;
  tab.baseUrl = url;
  wakeOver(tab);
  renderTabBar();
  renderProjectsRail(); // moon off
  // The server came back on a NEW port (ports are per-run), so the webview's
  // current document — loaded from the dead one — can never hot-reload again.
  // Repoint it, or the preview silently shows the pre-crash render forever.
  if (moved && tab.webview) loadRoute(tab.currentRoute, null, tab);
  // The project is awake again — bring back the agents that slept with it.
  relaunchSleptForTab(tab);
  window.radial.nativeChatRestore(repoDir).catch(() => {});
});

// Idle Claude agents were shut down with their sleeping project (or at quit).
// Their rows stay in the rail as dimmed "slept" entries; waking the project
// relaunches each one into its old conversation.
window.radial.onAgentsSlept(({ repoDir, slept }) => {
  const tab = tabByRepo(repoDir);
  if (!tab) return;
  for (const id of slept || []) {
    const term = (tab.terminals || []).find((t) => t.id === id);
    if (!term) continue;
    try { term.xterm && term.xterm.dispose(); } catch {}
    if (term.el && term.el.parentNode) term.el.remove();
    term.xterm = null; term.el = null; term.fit = null;
    term.detached = true; term._exited = false; term._working = false; term._needsReview = false;
    term._slept = true; term.sleptId = id;
  }
  renderTermLauncher();
  renderProjectsRail();
});

// Keep awake: the session is never parked (project sleep, quit, the idle limit)
// and the Mac stays awake while it runs — for a session you drive from your
// phone (Claude Code's remote control dies with the process). The flag lives on
// the pty in the daemon, so it survives a Radial restart with the session; the
// rail row shows an open eye (the peer of a sleeping project's moon).
async function toggleKeepAwake(term: TermSession) {
  const on = !term.keepAwake;
  let res = null;
  try { res = await window.radial.termKeepAwake(term.id, on); } catch {}
  if (!res || !res.ok) { toast((res && res.error) || 'Could not change that session. Is it still running?', 'err'); return; }
  term.keepAwake = on;
  renderProjectsRail();
  toast(on
    ? `${term.label} is kept awake: never parked, and this Mac stays awake while it runs.${res.daemonOutdated ? ' (Until the terminal service restarts, that holds only while Radial is open.)' : ''}`
    : `${term.label} can be parked again.`, 'ok');
}
// Flipped from outside the window — `radial agent keep`, maybe from the phone.
window.radial.onAgentsKeepAwake(({ id, on }) => {
  const term = findTermById(id);
  if (!term) return;
  term.keepAwake = !!on;
  renderProjectsRail();
});

// Static-server live reload: framework projects HMR on their own; for the
// built-in static server, main watches the repo and pings on change. Refresh
// like HMR would — keep the scroll position, and never yank a page out from
// under an inline text edit (the reload lands when the edit finishes).
window.radial.onDevStaticChanged(({ repoDir }) => {
  const tab = tabByRepo(repoDir);
  if (!tab || !tab.webview) return;
  // Mid inline text edit: the reload waits until the edit finishes.
  if (tab._inlineEditing) { tab._pendingStaticReload = true; return; }
  // Our own just-written structural edit: the optimistic DOM already shows it,
  // so DROP the reload — deferring it only moved the flash a second out, which
  // is exactly what read as flicker. (Not our write → reload normally.)
  if ((tab._structuralHoldUntil || 0) > Date.now()) return;
  softReloadPreview(tab);
});

// Agent state files: main polls .radial/ and pushes when comments.json changed
// on disk or an agent-requested launch check finished. State must never change
// silently on screen — vanishing pins read as data loss, so agent resolutions
// get a toast. resolvedBy tells them apart: '' means our own UI did it (that
// save also fires the poll; the refresh is idempotent and toast-free).
window.radial.onContextChanged(async ({ repoDir }) => {
  const tab = tabByRepo(repoDir);
  if (!tab || tab.id !== activeId) return;
  mentionDocs = { repoDir: null, list: [] };
  renderContext(tab);
  if (contextOpen && !ctxState?.dirty) await refreshOpenContextFromDisk(tab);
});
window.radial.onCommentsChanged(async ({ repoDir }) => {
  const tab = tabByRepo(repoDir);
  if (!tab) return;
  const before = new Map((tab.comments || []).map((c) => [c.id, !!c.resolved]));
  const list: ReviewComment[] = await refreshComments(tab);
  if (commentsOpen && tab.id === activeId) renderComments(tab);
  const flipped = list.filter((c) => c.resolved && c.resolvedBy && before.get(c.id) === false);
  const onVercel = flipped.filter((c) => c.source === 'vercel').length;
  const n = flipped.length - onVercel;
  if (n) toast(n > 1 ? `${n} comments resolved by your agent` : 'A comment was resolved by your agent', 'ok');
  if (onVercel) toast(onVercel > 1 ? `${onVercel} comments resolved on Vercel` : 'A comment was resolved on Vercel', 'ok');
  const added = list.filter((c) => c.source === 'vercel' && !c.resolved && !before.has(c.id)).length;
  if (added) toast(added > 1 ? `${added} new comments from Vercel` : 'New comment from Vercel', '');
});

// ── Vercel Toolbar comments: the pane's status line ─────────────────────────
// One sentence in the pane foot while the project is linked to Vercel: when the
// last pull happened, or what stands in the way (old CLI, signed out), with a
// single action. Hidden for projects that aren't linked.
function vercelStripHtml(st: VercelCommentsStatus): { html: string; warn: boolean } {
  const r = st.result;
  const busy = st.running;
  const btn = (label: string) => `<button type="button" class="cm-vercel-pull"${busy ? ' disabled' : ''}>${busy ? 'Pulling…' : label}</button>`;
  if (!r) return { html: `<span class="cm-vercel-msg">Vercel comments${busy ? ' · pulling…' : ''}</span>${busy ? '' : btn('Pull now')}`, warn: false };
  if (r.ok) {
    const when = st.lastAt ? timeAgo(st.lastAt) : '';
    return { html: `<span class="cm-vercel-msg" title="Comments left in the Vercel toolbar on this project’s deployments">Vercel comments${when ? ` · pulled ${when}` : ''}</span>${btn('Pull now')}`, warn: false };
  }
  const msg = r.code === 'unsupported-cli' ? 'Vercel comments need the Vercel CLI 59.1 or newer: npm i -g vercel@latest'
    : r.code === 'no-cli' ? 'Vercel comments need the Vercel CLI: npm i -g vercel'
    : r.code === 'not-authed' ? 'Sign in to the Vercel CLI (vercel login) to pull comments'
    : `Vercel comments: ${r.error || 'the pull failed'}`;
  return { html: `<span class="cm-vercel-msg" title="${escapeHtml(r.error || '')}">${escapeHtml(msg)}</span>${btn('Retry')}`, warn: true };
}
async function renderVercelStrip(tab: Tab | null, status?: VercelCommentsStatus) {
  const el = $('commentsVercel');
  if (!el || !tab || !tab.repoDir) return;
  let st: VercelCommentsStatus | null | undefined = status;
  if (!st) { try { st = await window.radial.commentsVercelStatus(tab.repoDir); } catch { st = null; } }
  if (!st || tab !== activeTab()) return;
  tab._vercel = st;
  if (!st.linked) { el.style.display = 'none'; el.innerHTML = ''; return; }
  const { html, warn } = vercelStripHtml(st);
  el.innerHTML = html;
  el.classList.toggle('warn', warn);
  el.style.display = '';
  const b = el.querySelector<HTMLButtonElement>('.cm-vercel-pull');
  if (b) b.onclick = () => pullVercelCommentsNow(tab);
}
async function pullVercelCommentsNow(tab: Tab) {
  if (!tab || !tab.repoDir) return;
  let r: import('../shared/radialApi').VercelPullResult | WindowCaughtFailure | null = null;
  try { r = await window.radial.commentsVercelPull(tab.repoDir); } catch (e) { r = { ok: false, error: String(e && (e as Error).message || e) }; }
  if (r && r.ok) {
    const parts: string[] = [];
    if (r.added) parts.push(`${r.added} new`);
    if (r.updated) parts.push(`${r.updated} updated`);
    if (r.resolved) parts.push(`${r.resolved} resolved`);
    toast(parts.length ? `Vercel comments: ${parts.join(', ')}` : (r.total ? 'Vercel comments are up to date' : 'No Vercel comments on this project yet'), parts.length ? 'ok' : '');
  } else if (r) toast(r.error || 'Could not pull Vercel comments', 'err');
  if (commentsOpen) renderComments(tab);
}
window.radial.onVercelComments(({ repoDir, status }) => {
  const tab = tabByRepo(repoDir);
  if (!tab) return;
  tab._vercel = status;
  if (commentsOpen && tab.id === activeId) renderVercelStrip(tab, status);
});
// "via Vercel" chips open the thread on vercel.com (rows live in the pane and the docked panel).
document.addEventListener('click', (e) => {
  const a = e.target && (e.target as Partial<Pick<Element, 'closest'>>).closest ? (e.target as Element).closest<HTMLAnchorElement>('a.cm-src') : null;
  if (!a) return;
  e.preventDefault(); e.stopPropagation();
  if (a.dataset.url) window.radial.openExternal(a.dataset.url);
}, true);

// Repo watcher fast ping: a terminal agent (or outside editor) touched source
// files. Reflect new/removed pages in the sidebar right away — refreshPages
// only re-renders when the page set actually changed, so routine edits are free.
window.radial.onFilesChanged(({ repoDir, files }) => {
  const tab = tabByRepo(repoDir);
  if (tab) refreshSidebarForChanges(tab, files);
});

window.radial.onLaunchCheckDone(({ repoDir, report }) => {
  const t = activeTab();
  if (!t || t.repoDir !== repoDir) return; // pane is per-active-tab; a later open loads the cached report
  const pane = $('pane-launch');
  if (!pane || pane.hidden) return;
  const prev = launchLast;
  renderLaunch(report);
  flashChangedLaunchChecks(prev, report);
});

// Briefly highlight the checks whose status moved since the last render, so a
// rescan landing mid-glance shows WHAT changed, not just a repainted list.
function flashChangedLaunchChecks(prev: LaunchCheckScan | null, report: LaunchCheckReport) {
  if (!prev || !prev.results || !report || report.ok === false) return;
  const was = new Map(prev.results.map((r) => [r.id, r.status]));
  const changed = (report.results || []).filter((r) => was.has(r.id) && was.get(r.id) !== r.status);
  for (const r of changed) {
    const el = document.querySelector('.launch-item[data-check="' + CSS.escape(r.id) + '"]');
    if (el) el.classList.add('changed');
  }
}
// Click a chat thumbnail → full-size view in-app (click or Escape closes).

async function softReloadPreview(tab: Tab) {
  const wv = tab.webview;
  if (!wv) return;
  tab._pendingStaticReload = false;
  let scroll = [0, 0];
  try { scroll = await wv.executeJavaScript('[scrollX, scrollY]') as number[]; } catch {}
  const request = tab._threadScrollRequest = (tab._threadScrollRequest || 0) + 1;
  tab._restoringScroll = request;
  const restore = async () => {
    wv.removeEventListener('did-finish-load', restore);
    if (tab._threadScrollRequest !== request) { if (tab._restoringScroll === request) tab._restoringScroll = null; return; }
    const position = await restorePreviewScroll(tab, scroll[0], scroll[1], request);
    if (tab._threadScrollRequest === request && position) tab._previewScroll = position;
    if (tab._restoringScroll === request) tab._restoringScroll = null;
  };
  wv.addEventListener('did-finish-load', restore);
  try { wv.reloadIgnoringCache(); } catch { tab._restoringScroll = null; }
}

// History/timeline — route to the matching tab.
window.radial.onHistoryState((s) => {
  const tab = tabByRepo(s.repoDir);
  if (tab) {
    tab.timeline = s.timeline || [];
    tab.cursor = s.cursor;
    tab.total = s.total;
    if (tab.id === activeId) renderActivity(tab);
    // A single-step undo/redo is just another file write — the dev server
    // hot-reloads it exactly like the edit it reverses. Hard-reloading here
    // (the old behavior) made ⌘Z feel like a page crash: flash, scroll reset,
    // seconds of wait. Only multi-file timeline NAVIGATION still reloads.
    if (['undo', 'redo'].includes(s.action)) {
      // Undo/redo is a reconcile point: a structural op left an OPTIMISTIC DOM
      // change (a moved/added/wrapped node) that reverting the source must undo
      // on screen. Clear the reload-suppress window so the dev-server reload
      // this write triggers is allowed through — else the DOM keeps the change
      // while disk no longer has it.
      tab._structuralHoldUntil = 0; tab._pendingStaticReload = false;
      if (tab.id === activeId && quickEdit && quickEdit.tab === tab && quickEdit.adj) { quickEdit.adj = null; }
    }
    if (['jump', 'jump-error', 'revert'].includes(s.action)) {
      if (tab.webview) { try { tab.webview.reload(); } catch {} }
      // The Design panel re-seeds from the post-reload capture: keeping adj
      // here would show the pre-undo values (the same-selector re-select
      // deliberately preserves adj to protect in-flight deltas — an undo
      // makes those moot).
      if (quickEdit && quickEdit.tab === tab && quickEdit.adj) { quickEdit.adj = null; }
      // If the changed file is the one open in the context view, reload it too.
      refreshOpenContextFromDisk(tab, s.action === 'redo' ? 'Redone' : 'Reverted');
    }
  }
  if (s.action === 'undo') toast(`Undid edit · ${s.relFile}`, 'ok');
  else if (s.action === 'redo') toast(`Redid edit · ${s.relFile}`, 'ok');
  else if (s.action === 'jump') toast('Previewing this version. Keep it or go back to latest.', '');
  else if (['jump-error', 'external-change'].includes(s.action)) toast('This file changed outside the edit being undone. Your newer work was kept; review its diff before restoring.', 'err');
  else if (s.action === 'revert') toast('Reverted. This is now the latest.', 'ok');
  else if (s.action === 'noop-undo') toast('Nothing to undo');
  else if (s.action === 'noop-redo') toast('Nothing to redo');
});

// ── Window requests from the control socket (the radial CLI / MCP) ──────────
// Only what needs the window: a screenshot of a preview, closing a tab, focusing
// one. Everything else the main process answers itself (plans/radial-agent-native.md).
async function cliNavigateTo(tab: Tab, route: string) {
  const wv = tab.webview;
  let url; try { url = new URL(route, tab.baseUrl!).href; } catch { return; }
  await new Promise<void>((resolve) => {
    let done = false;
    const fin = () => { if (done) return; done = true; wv.removeEventListener('did-stop-loading', fin); resolve(); };
    wv.addEventListener('did-stop-loading', fin);
    setTimeout(fin, 8000);
    try { wv.loadURL(url); } catch { fin(); }
  });
  await new Promise((r) => setTimeout(r, 600)); // fonts and images settle
}
// The rows a terminal's program shows now, as text: the bottom of its buffer,
// wherever the person has scrolled.
function termScreen(term: TermSession): string {
  const xterm = term.xterm; if (!xterm) return '';
  const buffer = xterm.buffer.active;
  return Array.from({ length: xterm.rows }, (_, i) => buffer.getLine(buffer.baseY + i)?.translateToString(true) || '').join('\n');
}
// The agent CLI in this terminal is asking a question of its own (signing in,
// trusting the folder, a first-run choice) instead of showing its input prompt
// (cliQuestion.ts). A task typed there is lost, and its Enter answers the question.
function cliAsking(term: TermSession): boolean {
  return !!term.engine && window.RadialCliQuestion.asksOwnQuestion(termScreen(term));
}
// Whether the CLI in this terminal is asking a question of its own now, before Radial types into it: by the PTY
// daemon's copy of its screen (main reads it as `radial agent question` does), or by this window's xterm once it has
// drawn all it was sent. Either is enough: after a restart the window's screen comes back as one replay it may not
// have drawn yet, and an older terminal service can't say. typed: text a send has typed into its input, whose rows
// are left out of either look (its own words are no question).
async function termAsking(term: TermSession, typed?: string): Promise<boolean> {
  if (!term.engine) return false;
  let daemon: boolean | null = null;
  try { daemon = await window.radial.termAsking(term.id, typed); } catch {}
  if (daemon) return true;
  await termDrawn(term);
  return typed ? window.RadialCliQuestion.asksAfterTyping(termScreen(term), typed) : cliAsking(term);
}
// Resolves once the xterm has drawn what was written to it so far (it parses in the background), or after a moment.
function termDrawn(term: TermSession): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, 500);
    try { if (term.xterm) term.xterm.write('', () => { clearTimeout(timer); resolve(); }); else resolve(); } catch { resolve(); }
  });
}
// The agent op's task into a terminal's CLI, as a person would type it
// (pasteVerified). A CLI asking a question of its own gets nothing now: the task
// goes in once the person has answered and the CLI has drawn its prompt (a second
// question waits too), unless the session ends or is closed first. landed is
// false then, and waiting true (agentPaste.ts typeTask).
function typeTask(term: TermSession, task: string, submit: boolean): Promise<AgentSent> {
  return window.RadialAgentPaste.typeTask(agentTermOf(term), task, submit);
}
// The agent op's hand-off to a project's first chat (RadialNativeChat.firstChat):
// the chat's terminal comes forward and the task is typed into its CLI, then
// submitted when the caller said so, as a person would in Terminal. Null when
// the chat can't take it: its terminal isn't in this window, someone used the
// chat meanwhile, or its CLI is waiting on a question of its own (sign in,
// trust this folder) that the typing would answer instead. One that asks while
// the task goes in gets it once that's answered: waiting.
async function handTaskToChat(tab: Tab, chat: ChatSession, task: string, label: string, submit: boolean): Promise<{ term: TermSession; landed: boolean; waiting: boolean } | null> {
  if (window.RadialNativeChat.visibleId() !== chat.id) await window.RadialNativeChat.select(chat.id);
  const term = (tab.terminals || []).find((t) => t._nativeChatId === chat.id && t.id === chat.terminalId && !t._exited);
  if (!term) return null;
  await showTerminal(tab, term);
  term._spawnedAt ||= chat.createdAt; // so whenTermReady waits out its CLI's first paint
  await whenTermReady(term);
  const ready = await window.RadialNativeChat.firstChat(tab);
  if (ready?.id !== chat.id || ready.viewMode !== 'terminal' || ready.terminalId !== term.id || ready.nativeInputNotice) return null;
  await window.radial.nativeChatUpdate(chat.id, { title: label }).catch(() => {});
  window.radial.termSetMeta(term.id, { label }); // `radial agent list` reads the pty's label
  const { landed, waiting } = await typeTask(term, task, submit);
  return { term, landed, waiting };
}
// The agent op's own chat, for a task the project's first chat can't take: a
// new chat, made and shown as New chat makes one, titled from the task (or its
// label) like other chats, with the task as its first message. Submitted, the
// chat sends it, and delivers it once its CLI is at its prompt (a question of
// the CLI's own waits for the person: waiting). Staged, it waits unsent in the
// chat's CLI input in Terminal view, or in its composer in Chat view. The id is
// the chat's CLI terminal, as for any session; a Codex chat shown in Chat view
// has none, and answers with its rail row's id.
async function startTaskChat(tab: Tab, eng: ChatEngine, task: string, label: string, submit: boolean): Promise<{ id: string; chat: ChatSession; landed: boolean; waiting: boolean }> {
  const created = await window.RadialNativeChat.createFor(tab, eng, submit ? task : undefined);
  await window.radial.nativeChatUpdate(created.id, { title: label }).catch(() => {});
  const chat = await window.radial.nativeChatGet(created.id);
  const term = chat.viewMode === 'terminal' ? (tab.terminals || []).find((t) => t._nativeChatId === chat.id && t.id === chat.terminalId && !t._exited) || null : null;
  if (chat.terminalId) window.radial.termSetMeta(chat.terminalId, { label }); // `radial agent list` reads the pty's label
  let landed = true, waiting = false;
  if (term) {
    await showTerminal(tab, term);
    term._spawnedAt ||= chat.createdAt; // so whenTermReady waits out its CLI's first paint
    await whenTermReady(term);
    if (submit) { waiting = await termAsking(term); landed = !waiting; }
    else ({ landed, waiting } = await typeTask(term, task, false));
  } else if (!submit) landed = window.RadialNativeChat.stage(task);
  return { id: chat.terminalId || 'native:' + chat.id, chat, landed, waiting };
}
window.radial.onCliRequest(async ({ reqId, op, payload }) => {
  const reply = (r: import('../shared/radialApi').CliResult) => window.radial.cliReply({ reqId, ...r });
  try {
    const p: WindowCliPayload = payload || {};
    if (op === 'shot') {
      const tab = tabByRepo(p.repoDir);
      if (!tab || !tab.webview) return reply({ ok: false, code: 'not-open', error: 'The project is not open in the window.' });
      if (tab.suspended) return reply({ ok: false, code: 'no-dev-server', error: 'The project is asleep.' });
      if (p.route) await cliNavigateTo(tab, p.route);
      let wcId = null; try { wcId = tab.webview.getWebContentsId(); } catch {}
      if (wcId == null) return reply({ ok: false, code: 'error', error: 'The preview is not reachable.' });
      const route = normRoute(tab.currentRoute || '/');
      const slug = route === '/' ? 'home' : route.replace(/^\//, '').replace(/\//g, '-');
      const name = `${tab.name || 'site'}-${slug}-full@2x-${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '')}`;
      const res = await window.radial.fullPageShot(wcId, name);
      return reply(res && res.ok ? { ok: true, path: res.path, scale: res.scale, route } : { ok: false, code: 'error', error: (res && res.error) || 'Capture failed.' });
    }
    if (op === 'close') {
      const tab = tabByRepo(p.repoDir);
      if (!tab) return reply({ ok: false, code: 'not-open', error: 'The project is not open.' });
      await closeTab(tab.id, { confirm: false, force: true });
      return reply({ ok: true });
    }
    if (op === 'reload') {
      const tab = tabByRepo(p.repoDir);
      // main's cliApi.reload maps only reason 'asleep'; anything else passes its code and error through.
      if (!tab) return reply({ ok: false, code: 'not-open', error: 'The project is not open in the window.' });
      if (tab.suspended) return reply({ ok: false, reason: 'asleep' });
      softReloadPreview(tab); return reply({ ok: true });
    }
    if (op === 'fields') {
      // The Content panel's own inventory, read from the live page (a route first if asked).
      const tab = tabByRepo(p.repoDir);
      if (!tab || !tab.webview) return reply({ ok: false, code: 'not-open', error: 'The project is not open in the window.' });
      if (tab.suspended) return reply({ ok: false, code: 'no-dev-server', error: 'The project is asleep.' });
      if (p.route) await cliNavigateTo(tab, p.route);
      tab._fieldsPending = false; ctRequestFields(tab, null);
      const t0 = Date.now();
      while (tab._fieldsPending && Date.now() - t0 < 10000) await new Promise((r) => setTimeout(r, 100));
      if (tab._fieldsPending) return reply({ ok: false, code: 'timeout', error: 'The page did not answer with its fields.' });
      return reply({ ok: true, route: normRoute(tab.currentRoute || '/'), fields: (tab._fields || []).map(({ thumb, inFocus, ...f }) => f) });
    }
    if (op === 'visibleAgents') {
      // What the person is looking at is never parked for being idle.
      const chatId = window.RadialNativeChat?.visibleId?.() || null;
      const at = agentTab(); // null on Home before initHomeTab knows its folder, or with a stale activeId
      const term = termOpen && at ? activeTerm(at) : null;
      return reply({ ok: true, chatIds: chatId ? [chatId] : [], termIds: term && !term._nativeChatId ? [term.id] : [] });
    }
    if (op === 'agentSend') {
      // A follow-up into a running session: the session comes forward, the text is
      // pasted, and submitted when the caller said so (an API caller is an explicit principal).
      // A CLI asking a question of its own gets nothing typed now: its Enter would answer
      // the question. The text goes in once the question is answered (typeTask), and the
      // reply says it waits, as the core's send does.
      const term = findTermById(p.id!);
      if (!term) return reply({ ok: false, code: 'not-found', error: `No session ${p.id} in the window.` });
      if (term._exited || term._slept) return reply({ ok: false, code: 'error', error: `${p.id} has ended.` });
      const tab = agentTabs().find((t) => (t.terminals || []).includes(term));
      if (tab) await selectProjectTerminal(tab.home ? 'home' : tab.id, term.id);
      await whenTermReady(term);
      const submit = p.submit !== false;
      const { landed, waiting } = await typeTask(term, p.text!, submit);
      return reply({ ok: true, id: term.id, submitted: submit, landed, sentAt: Date.now(), ...(waiting ? { waiting } : {}) });
    }
    if (op === 'home') {
      // The phone session: Home comes up and its agent starts if none is running.
      if (!homeActive) showHome();
      const existing = (homeTab.terminals || []).find((t) => !t._exited && !t._slept && t.xterm) || activeTerm(homeTab);
      if (existing && !existing._slept) { await showTerminal(homeTab, existing); return reply({ ok: true, id: existing.id, engine: existing.engine || 'shell', started: false }); }
      await engineAvailability();
      let eng = p.engine || (_engineAvail!.claude ? 'claude' : _engineAvail!.codex ? 'codex' : null);
      if (eng === 'shell') eng = null;
      if (eng && !_engineAvail![eng]) return reply({ ok: false, code: 'no-engine', error: `${eng} is not installed on this Mac.` });
      const term = (await addTerminal(homeTab, eng)) || activeTerm(homeTab);
      if (!term) return reply({ ok: false, code: 'error', error: 'Could not start the Home agent.' });
      return reply({ ok: true, id: term.id, engine: eng || 'shell', started: true });
    }
    if (op === 'agent') {
      // A real, visible session in the project (plans/radial-agent-native.md): the
      // project comes forward (waking if asleep), and the task goes to a chat when
      // chats are on, else to the project's terminal, submitted when the caller
      // said so, else staged for review. Only an API caller reaches this; the
      // app's own UI never auto-submits.
      const tab = tabByRepo(p.repoDir);
      if (!tab) return reply({ ok: false, code: 'not-open', error: 'The project is not open in the window.' });
      if (tab.id !== activeId || tab.suspended) await switchTab(tab.id);
      else await tab._switching?.catch(() => {}); // a switch still running, like the one an open starts
      if (tab.suspended) return reply({ ok: false, code: 'no-dev-server', error: 'The project is asleep and could not be woken.' });
      await engineAvailability();
      const eng = (p.engine as ChatEngine | null | undefined) || (_engineAvail!.claude ? 'claude' : _engineAvail!.codex ? 'codex' : _engineAvail!.cursor ? 'cursor' : null);
      if (!eng || !_engineAvail![eng]) return reply({ ok: false, code: 'no-engine', error: eng ? `${eng} is not installed on this Mac.` : 'No agent CLI (Claude Code, Codex, or Cursor) is installed on this Mac.' });
      const submit = !!p.submit, label = p.label || summarizeTask(p.task);
      // Opening a project boots its default agent (showTermForActive). Let that
      // settle, then hand the task to that session when it is still untouched —
      // freshly booted, unnamed, nothing typed — rather than stacking a second
      // one beside it. Anything the person has used gets a new session instead.
      // That boot starts when the switch to the project (awaited above) ends with
      // the terminal pane open, once the project's terminals are listed. Join it:
      // the pane boots one default agent at a time, so this pass either starts it
      // or finds it in flight and waits for it below.
      // With chats on, the default agent is the project's first chat, which the
      // chat panel starts when it shows the project: firstChat waits for that,
      // and answers the chat while nobody has used it.
      if (window.RadialNativeChat.enabled()) {
        const first = await window.RadialNativeChat.firstChat(tab);
        if (first?.engine === eng) {
          const handed = await handTaskToChat(tab, first, p.task!, label, submit);
          if (handed) return reply({ ok: true, id: handed.term.id, label, engine: eng, submitted: submit, landed: handed.landed, reused: true, startedAt: first.createdAt, ...(handed.waiting ? { waiting: true } : {}) });
        }
        // A task the first chat can't take (another engine, someone used it, or
        // its CLI is asking a question of its own) gets a chat of its own, as New
        // chat makes one. The open's first chat, unused, would stay beside it as a
        // second CLI for nothing: it goes.
        const own = await startTaskChat(tab, eng, p.task!, label, submit);
        if (first && first.id !== own.chat.id && await window.RadialNativeChat.discard(first.id)) {
          const left = (tab.terminals || []).find((t) => t._nativeChatId === first.id);
          if (left) closeTerminalSession(tab, left);
        }
        if (own.chat.state === 'error') return reply({ ok: false, code: 'error', error: own.chat.error || 'The chat could not send the task.' });
        return reply({ ok: true, id: own.id, label, engine: eng, submitted: submit, landed: own.landed, reused: false, startedAt: own.chat.createdAt, ...(own.waiting ? { waiting: true } : {}) });
      }
      // With chats off it is a plain terminal: the one the open booted when it's still untouched, else a new one.
      if (termOpen && agentTab() === tab && !activeTerm(tab)) await showTermForActive();
      for (let i = 0; i < 40 && tab._creatingDefaultTerm; i++) await new Promise((r) => setTimeout(r, 100));
      const fresh = (tab.terminals || []).find((t) => !t._nativeChatId && t.engine === eng && !t._exited && !t._slept && !t._renamed && !t._typedAt && t.label === engineLabel(eng) && t._spawnedAt && (Date.now() - t._spawnedAt) < 20000 && !/^new/.test(String(t.id)));
      // Nothing is typed into a CLI that is asking a question of its own (signing
      // in, trusting a new folder): the typing would answer it, and the task would
      // be lost. Submitted, the task rides as a new CLI's first prompt instead,
      // which the CLI keeps through that question; staged, typeTask types it in
      // once the person has answered.
      let term = fresh || null, landed = true, waiting = false, asking: TermSession | null = null;
      if (term) {
        await showTerminal(tab, term);
        await whenTermReady(term);
        if (submit && await termAsking(term)) { asking = term; term = null; waiting = true; }
        else { setTermTask(term, label); ({ landed, waiting } = await typeTask(term, p.task!, submit)); } // submit: paste, then Enter once it shows
      }
      if (!term) {
        term = await newTerminal(tab, eng, submit ? { initialText: p.task } : {});
        if (!term) return reply({ ok: false, code: 'error', error: 'Could not start the session.' });
        await showTerminal(tab, term);
        setTermTask(term, label);
        if (!submit) { await whenTermReady(term); ({ landed, waiting } = await typeTask(term, p.task!, false)); }
      }
      // The task's session is the one on screen. The open's untouched CLI, still
      // asking its question, would stay beside it as a second CLI for nothing: it goes.
      if (asking) closeTerminalSession(tab, asking);
      return reply({ ok: true, id: term.id, label: term.label, engine: eng, submitted: submit, landed, reused: term === fresh, startedAt: term._spawnedAt || Date.now(), ...(waiting ? { waiting } : {}) });
    }
    reply({ ok: false, code: 'bad-request', error: `Unknown window request: ${op}` });
  } catch (e) { reply({ ok: false, code: 'error', error: e && (e as Error).message ? (e as Error).message : String(e) }); }
});

// Enter in the Home search box with something that isn't a link: the same
// resolver the CLI uses (name → project; owner/repo → clone) or a clear miss.
async function openTargetFromHome(text: string) {
  let r: LooseUnion<import('../shared/radialApi').ResolveTargetResult> | null = null;
  try { r = await window.radial.resolveTarget(text); } catch {}
  if (r && r.ok && r.kind === 'path') { const hs = $('hgSearch'); if (hs) hs.value = ''; openProjectPath(r.dir); return; }
  if (r && r.ok && r.kind === 'clone') { const hs = $('hgSearch'); if (hs) hs.value = ''; openGitHubUrl(r.url); return; }
  if (r && r.code === 'ambiguous') { toast(`${r.candidates.length} projects match "${text}": ${r.candidates.slice(0, 3).map((c) => c.name).join(', ')}${r.candidates.length > 3 ? '…' : ''}. Pick one from the list.`, ''); return; }
  toast((r && r.error) || `No project called "${text}".`, 'err');
}

let collaborationPollRunning = false;
setInterval(async () => {
  const tab = activeTab();
  if (!tab || document.hidden || collaborationPollRunning) return;
  collaborationPollRunning = true;
  try {
    const state: LooseUnion<CollaborationState> = await window.radial.collaborationState(tab.repoDir);
    if (tab !== activeTab() || !state.isRepo) return;
    if (state.branch !== tab.branch) await renderBranchSwitch(tab);
    if (state.ok) { tab._ahead = state.ahead; tab._hasUpstream = state.exists; }
    if (typeof state.behind === 'number') tab._behind = state.behind;
    if (Array.isArray(state.changes)) {
      tab._unsaved = state.changes.length + (tab._ahead || 0);
      const chip = $('pmUnsaved');
      if (chip) { chip.textContent = `${state.changes.length} changed · ${tab._hasUpstream === false ? 'branch not pushed' : (tab._ahead ?? '?') + ' unpushed'}`; chip.style.display = ''; }
    }
  } catch { /* Keep the last observed state until the next refresh. */ } finally { collaborationPollRunning = false; }
}, 5000);
